const markBetweenChannelRevertMembershipConflicts = `-- name: MarkBetweenChannelRevertMembershipConflicts :execrows
UPDATE firmware_rollout_member member
SET state = 'attention_required',
    last_error = 'device no longer belongs to the rollout target channel',
    settled_at = CURRENT_TIMESTAMP,
    owner_released_at = CURRENT_TIMESTAMP,
    revision = member.revision + 1
WHERE member.rollout_id = $1
  AND member.org_id = $2
  AND member.state = 'reverting'
  AND member.owner_released_at IS NULL
  AND NOT EXISTS (
      SELECT 1
      FROM device_set_membership membership
      WHERE membership.org_id = member.org_id
        AND membership.device_id = member.device_id
        AND membership.device_set_type = 'channel'
        AND membership.device_set_id = $3
  )
`

type MarkBetweenChannelRevertMembershipConflictsParams struct {
	RolloutID       uuid.UUID
	OrgID           int64
	TargetChannelID int64
}

func (q *Queries) MarkBetweenChannelRevertMembershipConflicts(ctx context.Context, arg MarkBetweenChannelRevertMembershipConflictsParams) (int64, error) {
	result, err := q.exec(ctx, q.markBetweenChannelRevertMembershipConflictsStmt, markBetweenChannelRevertMembershipConflicts, arg.RolloutID, arg.OrgID, arg.TargetChannelID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

